import React from "react";
import { useState, useEffect, useRef } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-toastify";
import Select from "react-select";
import { GetAppDate } from "../dataservice/getAppDate";
import { GetCmbLedgers } from "../dataservice/getCmbLedgers";
import { GetQData } from "../dataservice/getQData";
import { GetVoucherData } from "../dataservice/getVoucherData";
import { GetActionList } from "../dataservice/getActionList";
import { useSearchParams, useNavigate } from "react-router-dom";

import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";

import apiAcc from "../../components/api/AccWebcall";
import api from "../../components/api/Webcall";
import appsettings from "../../appsettings.json"
const apiendpoints = appsettings.ApiEndpoints;

function ReceiptInit() {

    const navigate = useNavigate();
    const { register, handleSubmit, getValues, setValue } = useForm();
    const [searchParams, setSearchParams] = useSearchParams();

    let qDet = useRef(JSON.parse(decompressBase64(atob(searchParams.get("_q")))));

    const [actLst, setActionLst] = useState([]);

    const [ledgid, setLedgId] = useState(0);

    const [ledgers, setLedgers] = useState([]);
    const [cashLedgers, setCashLedgers] = useState([]);
    const [bankLedgers, setBankLedgers] = useState([]);
    const [cashbankLedgers, setCashBankLedgers] = useState([]);
    const [otherLedgers, setOtherLedgers] = useState([]);

    const [grLedgDet, setGrLedgDet] = useState([{ "cmbLedgerId": 0, "txtCurrency": "", "txtAmount": 0, "txtExcngRate": 0, "txtLcAmount": 0 }]);

    const handleAdd = () => {
        const ledgDet = [...grLedgDet, [{ "cmbLedgerId": 0, "txtCurrency": "", "txtAmount": 0, "txtExcngRate": 0, "txtLcAmount": 0 }]];
        setGrLedgDet(ledgDet);
    }

    const onChange_cmbLedgerId = (obj) => {
        setLedgId(obj.value);
        

        let lgr = ledgers["cledg"].find(x => x.lgid == obj.value);
        if (lgr === undefined) {
            lgr = ledgers["bledg"].find(x => x.lgid == obj.value);
        }


        if (lgr !== undefined) {
            setValue("cmbLedgerId", lgr["lgid"]);
            setValue("txtCurrency", lgr["currcod"]);
            setValue("txtExcngRate", lgr["rate"]);
            setValue("txtLcAmount", getValues("txtAmount") * lgr["rate"]);
        }
        else {
            setValue("cmbLedgerId", 0);
            setValue("txtCurrency", "");
            setValue("txtExcngRate", 0);
            setValue("txtLcAmount", 0);
        }
    }

    const onChange_txtAmount = (obj) => {
        const lcamt = obj.target.value * getValues("txtExcngRate");
        setValue("txtLcAmount", lcamt.toLocaleString(undefined, { maximumFractionDigits: 2 }).replaceAll(',', ''));
    }

    const onChange_txtExcngRate = (obj) => {
        setValue("txtLcAmount", getValues("txtAmount") * obj.target.value);
    }

    const onChange_grcmbLedgerId = (obj, i) => {
      
        const ledgDet = [...grLedgDet];
        ledgDet[i]["cmbLedgerId"] = obj.value;

        const lgr = ledgers["oledg"].find(x => x.lgid == obj.value);
        if (lgr !== undefined) {
            ledgDet[i]["txtCurrency"] = lgr["currcod"];
            ledgDet[i]["txtExcngRate"] = lgr["rate"];
            ledgDet[i]["txtLcAmount"] = ledgDet[i]["txtAmount"] * lgr["rate"];
        }
        else {
            ledgDet[i]["txtCurrency"] = "";
            ledgDet[i]["txtExcngRate"] = 0;
            ledgDet[i]["txtLcAmount"] = 0;
        }
        setGrLedgDet(ledgDet);
    }

    const onChange_grtxtAmount = (obj, i) => {
        const ledgDet = [...grLedgDet];
        ledgDet[i]["txtAmount"] = obj.target.value;
        ledgDet[i]["txtLcAmount"] = obj.target.value * ledgDet[i]["txtExcngRate"];
        setGrLedgDet(ledgDet);
    }

    const onChange_grtxtExcngRate = (obj, i) => {
        const ledgDet = [...grLedgDet];
        ledgDet[i]["txtExcngRate"] = obj.target.value;
        ledgDet[i]["txtLcAmount"] = obj.target.value * ledgDet[i]["txtAmount"];
        setGrLedgDet(ledgDet);
    }

    const handleDelete = (i) => {
        const ledgDet = [...grLedgDet];
        ledgDet.splice(i, 1);
        setGrLedgDet(ledgDet);
    }

    const fetchAppDate = async () => {
        const appDate = await GetAppDate();
        setValue("txtDate", appDate["AppDate"]);
    }

    const fetchLedgers = async () => {
        const ledgs = await GetCmbLedgers(0, getValues('txtDate'));
        setLedgers(ledgs);

        const cashBank = [];
        cashBank.push({ value: 0, label: '- Select -' });

        Object.keys(ledgs).forEach(k => {
            switch (k) {
                case "cledg":
                    const cledg = [];
                    cledg.push({ value: 0, label: '- Select -' });
                    ledgs[k].map((data, i) => { 
                        cledg.push({ value: data.lgid, label: data.lgna }); 
                        cashBank.push({ value: data.lgid, label: data.lgna }); 
                    });
                    setCashLedgers(cledg);
                    break;

                case "bledg":
                    const bledg = [];
                    bledg.push({ value: 0, label: '- Select -' });
                    ledgs[k].map((data, i) => { 
                        bledg.push({ value: data.lgid, label: data.lgna });
                        cashBank.push({ value: data.lgid, label: data.lgna });
                    });
                    setBankLedgers(bledg);
                    break;

                case "oledg":
                    const oledg = [];
                    oledg.push({ value: 0, label: '- Select -' });
                    ledgs[k].map((data, i) => { oledg.push({ value: data.lgid, label: data.lgna }) });
                    setOtherLedgers(oledg);
                    break;

                default:
                    break;
            }

            setCashBankLedgers(cashBank);

        });

        console.log(cashbankLedgers);

    };

    const onBlur_txtDate = () => {
        fetchLedgers();
    }

    const onSubmit = (e) => {

        let frmData = {};

        /* Validate Data */
        frmData["_QMovement"] = {};
        frmData["_QMovement"]["_cmbAction"] = getValues("cmbAction");
        frmData["_QMovement"]["_Comment"] = getValues("txtComment");
        frmData["_QMovement"]["_StartTime"] = qDet.starttime;

        frmData["entid"] = 0;
        frmData["btchno"] = 0;
        frmData["valdt"] = getValues("txtDate");
        frmData["votyid"] = 1; // Reference-Type to Receipt
        frmData["lgrid"] = getValues("cmbLedgerId");
        frmData["drcr"] = "D";
        frmData["amt"] = Number(getValues("txtAmount"));
        frmData["exrate"] = getValues("txtExcngRate");
        frmData["narr"] = getValues("txtNaration");

        frmData["det"] = [];
        grLedgDet.map((data, i) => {
            let det = {}
            det["lgrid"] = data["cmbLedgerId"];
            det["amt"] = Number(data["txtAmount"]);
            det["narr"] = getValues("txtNaration");
            det["exrate"] = data["txtExcngRate"];
            frmData["det"].push(det);
        });

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Validate Trans", orgid: "", vendid: "_Acc" };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};
        apiAcc.post(apiendpoints.VlidtTran, compressBase64(data), reqHdr)
            .then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));
                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {

                            e.target.disabled = false;

                            if (res.fdr) {
                                setTimeout(() => {

                                    let strMsg = "";
                                    res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                    toast.error(strMsg);

                                }, 300);
                            }
                        }
                        else {

                            const convID = generateUUID();
                            const frmHdr = { convid: convID, tag: "Submit Q", orgid: "", vendid: "_Acc" };
                            const data = { hdr: frmHdr, body: frmData, _sev: qDet.current };
                            const reqHdr = {};

                            api.post(apiendpoints.CScrSubmitQ, compressBase64(data), reqHdr)
                                .then(function (response) {
                                    const res = JSON.parse(decompressBase64(response.data));

                                    if (res) {
                                        if (res.hdr) {
                                            if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {

                                                e.target.disabled = false;

                                                if (res.fdr) {
                                                    setTimeout(() => {

                                                        let strMsg = "";
                                                        res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                                        toast.error(strMsg);

                                                    }, 300);
                                                }
                                            }
                                            else {
                                                setTimeout(() => { toast.success("Successfully submited"); }, 300);
                                                navigate("/Home");
                                            }
                                        }
                                    }
                                });
                        }
                    }
                }
            });
    }

    const fetchActionList = async () => {
        const actLst = await GetActionList(qDet.current.stgid);
        if (actLst) {
            if (actLst.hdr) {
                if (actLst.hdr.rst && actLst.hdr.rst !== "SUCCESS") {

                    if (actLst.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            actLst.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    setActionLst(actLst.body.act);
                }
            }
        }
    }

    const fetchVoData = () => {

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Q Data", orgid: "", vendid: "_Acc" };
        const frmData = { qid: qDet.current.qid, scrid: qDet.current.scrid, stgid: qDet.current.stgid };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};
        api.post(apiendpoints.CScrQData, compressBase64(data), reqHdr)
            .then(function (response) {
                const qData = JSON.parse(decompressBase64(response.data));

                if (qData) {
                    if (qData.hdr) {
                        if (qData.hdr.rst && qData.hdr.rst !== "SUCCESS") {
                            if (qData.fdr) {

                                setTimeout(() => {
                                    let strMsg = "";
                                    qData.fdr.map((data) => { strMsg += data.rstmsg + ", " });
                                    toast.error(strMsg);
                                }, 300);
                            }
                        }
                        else {

                            qData.body["_stage"] = "initiation";
                            const convID = generateUUID();
                            const frmHdr = { convid: convID, tag: "Screen Transaction Data", orgid: "", vendid: "_Acc" };
                            const data = { hdr: frmHdr, body: qData.body };
                            const reqHdr = {};
                            apiAcc.post(apiendpoints.VoData, compressBase64(data), reqHdr)
                                .then(function (response) {
                                    const voData = JSON.parse(decompressBase64(response.data));
                                    if (voData) {
                                        if (voData.hdr) {
                                            if (voData.hdr.rst && voData.hdr.rst !== "SUCCESS") {
                                                if (voData.fdr) {

                                                    setTimeout(() => {
                                                        let strMsg = "";
                                                        qData.fdr.map((data) => { strMsg += data.rstmsg + ", " });
                                                        toast.error(strMsg);
                                                    }, 300);
                                                }
                                            }
                                            else
                                                {
                                                    if (voData.body.vodata.valdt === undefined)
                                                    {
                                                        fetchAppDate();
                                                    }

                                                    fetchLedgers(); 

                                                    if (voData.body.vodata)
                                                    {
                                                        bindData(voData.body.vodata);
                                                    }

                                                }
                                        }
                                    }

                                });
                        }
                    }
                }

            });
    }


    const bindData = (vodata) => {

        if (vodata.valdt) {
            setValue("txtDate", vodata.valdt);
        }

        if (vodata.lgrid) {
            setLedgId(vodata.lgrid);
            setValue("cmbLedgerId", vodata.lgrid);
        }

        if (vodata.amt) {
            setValue("txtAmount", vodata.amt);
        }

        if (vodata.curr) {
            setValue("txtCurrency", vodata.curr);
        }

        if (vodata.currrate) {
            setValue("txtExcngRate", vodata.currrate);
        }

        if (vodata.lcamt) {
            setValue("txtLcAmount", vodata.lcamt);
        }

        if (vodata.narr) {
            setValue("txtNaration", vodata.narr);
        }

        if (vodata.det)
        {
            let ledgDet = [];
            vodata.det.map((data, i) => {
                ledgDet = [...ledgDet, { "cmbLedgerId":data.lgrid, "txtCurrency":data.curr, "txtAmount":data.amt, "txtExcngRate": data.currrate, "txtLcAmount": data.lcamt }];
            });
            setGrLedgDet(ledgDet);
        }
    }


    const onCancel = (e) => {

        let frmData = {};
        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Cancel Q", orgid: "", vendid: "_Acc" };
        const data = { hdr: frmHdr, body: frmData, _qdet: qDet.current };
        const reqHdr = {};
        api.post(apiendpoints.CScrCancelQ, compressBase64(data), reqHdr)
            .then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));

                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                            
                            e.target.disabled = false;

                            if (res.fdr) {
                                setTimeout(() => {

                                    let strMsg = "";
                                    res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                    toast.error(strMsg);

                                }, 300);
                            }
                        }
                        else {
                            setTimeout(() => { toast.success("Successfully cancled"); }, 300);
                            navigate("/Home");
                        }
                    }
                }

            });
    }

    /*  Use Effect */
    useEffect(() => {
        fetchActionList();
        fetchVoData();
    }, []);

    
    return (

        <>
            {
                (qDet !== null && ledgid !== null) ?
                    <>
                        <div className="row pad-top-0-5em pad-left-15">

                            <div className="card-header">
                                <strong className="card-title">Receipt Entry</strong>
                            </div>

                        </div>

                        <div className="row">

                            <div className="col-md-9 pad-left-2em">

                                <div className="row pad-bottom-0-5em">

                                    <div className="col-md-4">
                                        <label htmlFor="txtDate" className="form-label">Date</label>
                                        <input type="date" className="form-control"
                                            {...register("txtDate", { value: new Date(), onBlur: (e) => onBlur_txtDate() })}
                                        />
                                    </div>

                                    <div className="col-md-8">
                                        <label htmlFor="cmbLedgerId" className="form-label">Debit Ledger</label>
                                        <Select {...register("cmbLedgerId")} options={cashbankLedgers} 
                                            value={cashbankLedgers.find(x => x.value === ledgid)}
                                            onChange={e => onChange_cmbLedgerId(e)}> </Select>
                                    </div>

                                </div>

                                <div className="row pad-bottom-0-5em">

                                    <div className="col-md-4">
                                        <label htmlFor="txtAmount" className="form-label">Amount</label>
                                        <input type="number" className="form-control"
                                            {...register("txtAmount")} onChange={e => onChange_txtAmount(e)}
                                        />
                                    </div>

                                    <div className="col-md-2">
                                        <label htmlFor="txtCurrency" className="form-label">Currency</label>
                                        <input type="text" className="form-control"
                                            disabled="disabled" {...register("txtCurrency", { onBlur: (e) => { } })}
                                        />
                                    </div>

                                    <div className="col-md-3">
                                        <label htmlFor="txtExcngRate" className="form-label">Exchange Rate</label>
                                        <input type="number" className="form-control"
                                            {...register("txtExcngRate", { onChange: (e) => onChange_txtExcngRate(e) })}
                                        />
                                    </div>

                                    <div className="col-md-3">
                                        <label htmlFor="txtLcAmount" className="form-label">LC Value</label>
                                        <input type="number" className="form-control"
                                            disabled="disabled" {...register("txtLcAmount", { onBlur: (e) => { } })}
                                        />
                                    </div>

                                </div>

                                <div className="row pad-bottom-0-5em">

                                    <div className="col-md-12">
                                        <label htmlFor="txtNaration" className="form-label">Naration</label>
                                        <input type="text" className="form-control"
                                            {...register("txtNaration", { onBlur: (e) => { } })}
                                        />
                                    </div>

                                </div>

                                <br />

                                <div className="row">

                                    <div className="col-md-4">
                                        <label htmlFor="cmbLedgerId_1" className="form-label">Credit Ledger</label>
                                    </div>

                                    <div className="col-md-1">
                                        <label htmlFor="txtCurrency_1" className="form-label">Currency</label>
                                    </div>

                                    <div className="col-md-3">
                                        <label htmlFor="txtAmount_1" className="form-label">Amount</label>
                                    </div>

                                    <div className="col-md-1">
                                        <label htmlFor="txtExcngRate_1" className="form-label">Ex Rate</label>
                                    </div>

                                    <div className="col-md-2">
                                        <label htmlFor="txtLcAmount_1" className="form-label">LC Value</label>
                                    </div>

                                    <div className="col-md-1">
                                        <button className="btn link" type="button" onClick={(e) => handleAdd(e)} >addnew</button>
                                    </div>

                                </div>

                                {grLedgDet.map((data, i) => {

                                    return (

                                        <div className="row">

                                            <div className="col-md-4">
                                                <Select value={otherLedgers.find(x => x.value === data["cmbLedgerId"])} options={otherLedgers} onChange={e => onChange_grcmbLedgerId(e, i)}> </Select>
                                            </div>

                                            <div className="col-md-1">
                                                <input type="text" value={data["txtCurrency"]} className="form-control" disabled="disabled" />
                                            </div>

                                            <div className="col-md-3">
                                                <input type="number" value={data["txtAmount"]} className="form-control" onChange={e => onChange_grtxtAmount(e, i)} />
                                            </div>

                                            <div className="col-md-1">
                                                <input type="number" value={data["txtExcngRate"]} className="form-control" onChange={e => onChange_grtxtExcngRate(e, i)} />
                                            </div>

                                            <div className="col-md-3">
                                                <input type="number" value={data["txtLcAmount"]} className="form-control" disabled="disabled" />
                                            </div>

                                            <div className="col-md-3">
                                                <button className="btn link" type="button" onClick={() => handleDelete(i)} >delete</button>
                                            </div>

                                        </div>
                                    )

                                })}


                            </div>



                            <div className="col-md-3">

                                <div className="row col-md-12 pad-bottom-0-5em" >

                                    <label htmlFor="cmbAction" className="form-label">Action</label>

                                    <select {...register("cmbAction")} className="form-control" >
                                        <option value="">- Select -</option>
                                        {(actLst) ?
                                            actLst.map((i) =>
                                                (<option key={i.actid} value={i.actid}>{i.actna}</option>))
                                            : ""}
                                    </select>

                                </div>

                                <div className="row col-md-12 pad-bottom-0-5em" >
                                    <label htmlFor="txtComment" className="form-label">Comment</label>
                                    <textarea type="text" className="form-control" {...register("txtComment")} rows="3" ></textarea>
                                </div>

                                <div className="row  col-md-12">

                                    <button className="btn btn-hover color-5 btn-sm  m-2" type="button" 
                                         onClick={(e) => { onSubmit(e); e.target.disabled = true; } } >
                                        Submit
                                    </button>

                                    <button className="btn btn btn-hover color-10 btn-sm  m-2" type="button" 
                                            onClick={(e) => { onCancel(e); e.target.disabled = true; }} >
                                        Cancel
                                    </button>

                                </div>


                            </div>


                        </div>

                    </>

                    : <> <h4> Loading.... </h4> </>
            }
        </>
    );
}

export default ReceiptInit;
